/*!
 * @name 洋仔聚合音源
 * @description 杰翔聚合 + 轻量四平台 + 星澜聚合 + 星海音乐，四源自动切换，一个链接搞定
 * @version v1.0.0
 * @author 洋仔（合并自社区开源音源，原作者见仓库 README）
 * @homepage https://github.com/szyshr199312/lx-source
 */

const LX = globalThis.lx
if (!LX) throw new Error('[洋仔聚合] 未检测到 lx 环境，请确认导入的是洛雪自定义源')

const { EVENT_NAMES, request, on, send } = LX

/* ==================== base64 -> UTF-8 ==================== */
const B64CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
const B64MAP = {}
for (let i = 0; i < B64CHARS.length; i++) B64MAP[B64CHARS[i]] = i

function utf8decode(bytes) {
  let out = ''
  let i = 0
  while (i < bytes.length) {
    const b = bytes[i++]
    if (b < 0x80) {
      out += String.fromCharCode(b)
    } else if (b >= 0xC0 && b < 0xE0) {
      out += String.fromCharCode(((b & 0x1F) << 6) | (bytes[i++] & 0x3F))
    } else if (b >= 0xE0 && b < 0xF0) {
      out += String.fromCharCode(((b & 0x0F) << 12) | ((bytes[i++] & 0x3F) << 6) | (bytes[i++] & 0x3F))
    } else {
      const cp = ((b & 0x07) << 18) | ((bytes[i++] & 0x3F) << 12) | ((bytes[i++] & 0x3F) << 6) | (bytes[i++] & 0x3F)
      const off = cp - 0x10000
      out += String.fromCharCode(0xD800 + (off >> 10), 0xDC00 + (off & 0x3FF))
    }
  }
  return out
}

function b64decode(input) {
  const s = String(input).replace(/[^A-Za-z0-9+/]/g, '')
  const bytes = []
  for (let i = 0; i < s.length; i += 4) {
    const c1 = B64MAP[s[i]]
    const c2 = B64MAP[s[i + 1]]
    const c3 = B64MAP[s[i + 2]]
    const c4 = B64MAP[s[i + 3]]
    bytes.push((c1 << 2) | (c2 >> 4))
    if (c3 !== undefined) bytes.push(((c2 & 15) << 4) | (c3 >> 2))
    if (c4 !== undefined) bytes.push(((c3 & 3) << 6) | c4)
  }
  return utf8decode(bytes)
}

/* ==================== 子源定义 ==================== */
const SUB_DEFS = [
  { id: "jiexiang", label: "杰翔聚合", code: "" },
  { id: "qingliang", label: "轻量四平台", code: "" },
  { id: "xinglan", label: "星澜聚合", code: "" },
  { id: "xinghai", label: "星海音乐", code: "" }
]

/* ==================== 沙箱加载子源 ==================== */
const SUBS = []

for (let i = 0; i < SUB_DEFS.length; i++) {
  const def = SUB_DEFS[i]
  const sub = { id: def.id, label: def.label, handler: null, inited: null, broken: false, reason: '' }

  const fakeLx = {
    EVENT_NAMES: EVENT_NAMES,
    request: request,
    on: function (ev, fn) {
      if (ev === EVENT_NAMES.request) sub.handler = fn
    },
    send: function (ev, data) {
      if (ev === EVENT_NAMES.inited) {
        sub.inited = data
        return
      }
      try { send(ev, data) } catch (e) {}
    },
    utils: LX.utils,
    env: LX.env,
    version: LX.version,
    currentScriptInfo: LX.currentScriptInfo,
  }

  const prev = globalThis.lx
  try {
    globalThis.lx = fakeLx
    const runner = new Function(b64decode(def.code))
    runner()
  } catch (e) {
    sub.broken = true
    sub.reason = e && e.message ? e.message : String(e)
  } finally {
    globalThis.lx = prev
  }

  SUBS.push(sub)
}

/* ==================== 调度 ==================== */
const PER_SUB_TIMEOUT = 5000

function invoke(sub, params) {
  return new Promise(function (resolve, reject) {
    let done = false
    const timer = setTimeout(function () {
      if (!done) {
        done = true
        reject(new Error('超时 ' + PER_SUB_TIMEOUT + 'ms'))
      }
    }, PER_SUB_TIMEOUT)

    function ok(v) {
      if (done) return
      done = true
      clearTimeout(timer)
      resolve(v)
    }
    function no(e) {
      if (done) return
      done = true
      clearTimeout(timer)
      reject(e instanceof Error ? e : new Error(String(e)))
    }

    try {
      const r = sub.handler(params)
      if (r && typeof r.then === 'function') {
        r.then(ok, no)
      } else if (r !== undefined && r !== null && r !== '') {
        ok(r)
      } else {
        no(new Error('返回空'))
      }
    } catch (e) {
      no(e)
    }
  })
}

on(EVENT_NAMES.request, function (params) {
  const source = params.source
  const queue = SUBS.filter(function (s) {
    if (!s.handler) return false
    if (s.inited && s.inited.sources && !s.inited.sources[source]) return false
    return true
  })

  if (!queue.length) {
    return Promise.reject(new Error('[洋仔聚合] 没有可用音源处理 ' + source))
  }

  const errors = []
  let idx = 0

  function next() {
    if (idx >= queue.length) {
      return Promise.reject(new Error('[洋仔聚合] 全部音源失败（试了 ' + queue.length + ' 个）\n' + errors.join('\n')))
    }
    const s = queue[idx++]
    return invoke(s, params).catch(function (e) {
      errors.push('  ' + s.label + ': ' + (e && e.message ? e.message : String(e)))
      return next()
    })
  }

  return next()
})

/* ==================== 初始化声明 ==================== */
const QUALITY = {
  tx: ['128k', '320k', 'flac'],
  wy: ['128k', '320k', 'flac'],
  kw: ['128k', '192k', '320k', 'flac', 'flac24bit'],
  kg: ['128k', '320k', 'flac'],
  mg: ['128k', '320k', 'flac'],
}

const PLATFORM_NAME = {
  tx: 'QQ音乐',
  wy: '网易云音乐',
  kw: '酷我音乐',
  kg: '酷狗音乐',
  mg: '咪咕音乐',
}

const sources = {}
Object.keys(QUALITY).forEach(function (k) {
  sources[k] = {
    name: PLATFORM_NAME[k] + '（洋仔聚合）',
    type: 'music',
    actions: ['musicUrl'],
    qualitys: QUALITY[k],
  }
})

send(EVENT_NAMES.inited, {
  status: true,
  openDevTools: false,
  sources: sources,
})

/* ==================== 启动日志 ==================== */
try {
  const okList = SUBS.filter(function (s) { return s.handler }).map(function (s) { return s.label })
  const badList = SUBS.filter(function (s) { return !s.handler }).map(function (s) { return s.label + '(' + s.reason + ')' })
  console.log('[洋仔聚合音源 v1.0.0] 已加载，可用子源 ' + okList.length + '/' + SUBS.length)
  if (okList.length) console.log('[洋仔聚合] 生效: ' + okList.join(' / '))
  if (badList.length) console.log('[洋仔聚合] 失败: ' + badList.join(' / '))
} catch (e) {}
